def merge_dict(a, b):
    out = dict(a or {}); out.update(b or {}); return out
def add_list(a, b):
    return (a or []) + (b or [])
REDUCERS = {"analysis": merge_dict, "timeline": add_list}

def apply(state, delta):
    for k, v in delta.items():
        state[k] = REDUCERS[k](state.get(k), v) if k in REDUCERS else v
    return state

state = {"analysis": {}, "timeline": []}
rca_a = {"analysis": {"rca_a": {"root_cause": "디스크 가득 참"}}, "timeline": ["rca_a 끝"]}
rca_b = {"analysis": {"rca_b": {"root_cause": "디스크 가득 참"}}, "timeline": ["rca_b 끝"]}
for d in (rca_a, rca_b):
    apply(state, d)
print(sorted(state["analysis"]), state["timeline"])
# ['rca_a', 'rca_b'] ['rca_a 끝', 'rca_b 끝']

ready = all(state["analysis"].get(k, {}).get("root_cause") for k in ("rca_a", "rca_b"))
print("go" if ready else "wait")   # go

naive = {}
for d in (rca_a, rca_b):
    naive.update(d)
print(sorted(naive["analysis"]))     # ['rca_b']

import json
tool = {"name": "search_tickets",
        "inputSchema": {"type": "object",
                        "properties": {"keyword": {"type": "string"},
                                       "limit": {"type": "integer", "maximum": 20}},
                        "required": ["keyword"]}}

def check(args, schema):
    errs = [f"{k} 빠짐" for k in schema["required"] if k not in args]
    for k, v in args.items():
        p = schema["properties"].get(k)
        if p is None:
            errs.append(f"{k} 모르는 인자"); continue
        if "maximum" in p and isinstance(v, int) and v > p["maximum"]:
            errs.append(f"{k} > {p['maximum']}")
    return errs

for i, args in enumerate([{"keyword": "OOMKilled", "limit": 5},
                          {"limit": 100, "team": "infra"}], 1):
    req = {"jsonrpc": "2.0", "id": i, "method": "tools/call",
           "params": {"name": tool["name"], "arguments": args}}
    e = check(args, tool["inputSchema"])
    print("통과" if not e else "거절: " + ", ".join(e))
# 통과
# 거절: keyword 빠짐, limit > 20, team 모르는 인자
